+	u8 lsb_idx;
+	u8 msb_idx;
+	bool has_msb;
+	u8 flag_idx;
+	u32 flag_mask;
+	bool is_addr_when_set;
+	u8 size_idx;
+	u8 size_shift;
+	u32 size_mask;
+	u32 buf_size;
