>> +    mc->led_cdev.brightness = brightness;
>> +    led_mc_calc_color_components(&ldev->mc_cdev, brightness);
>> +
>> +    mutex_lock(&ldev->dev_lock);
>> +    ret = lamparray_hw_set_state(ldev, r, g, b, brightness);
