+int wave6_vpu_dec_get_output_info(struct vpu_instance *inst, struct dec_output_info *info)
+{
+	struct dec_info *p_dec_info;
+	u32 reg_val, i;
+	int decoded_idx = -1, disp_idx = -1;
+	int ret;
+
+	if (WARN_ON(!info))
+		return -EINVAL;
+
+	guard(mutex)(&inst->dev->hw_lock);
+
+	p_dec_info = &inst->codec_info->dec_info;
+
+	ret = wave6_send_query(inst->dev, inst->id, inst->std, W6_QUERY_OPT_GET_RESULT);
+	if (ret) {
+		info->rd_ptr = p_dec_info->stream_rd_ptr;
+		info->wr_ptr = p_dec_info->stream_wr_ptr;
+		return ret;
+	}
+
+	info->decoding_success = vpu_read_reg(inst->dev, W6_RET_DEC_DECODING_SUCCESS);
+	if (!info->decoding_success)
+		info->error_reason = vpu_read_reg(inst->dev, W6_RET_DEC_ERR_INFO);
+	else
+		info->warn_info = vpu_read_reg(inst->dev, W6_RET_DEC_WARN_INFO);
+
+	reg_val = vpu_read_reg(inst->dev, W6_RET_DEC_PIC_TYPE);
+	info->ctu_size = DEC_PIC_TYPE_CTU_SIZE(reg_val);
+	info->nal_type = DEC_PIC_TYPE_NAL_UNIT_TYPE(reg_val);
+
+	if (reg_val & DEC_PIC_TYPE_B)
+		info->pic_type = PIC_TYPE_B;
+	else if (reg_val & DEC_PIC_TYPE_P)
+		info->pic_type = PIC_TYPE_P;
+	else if (reg_val & DEC_PIC_TYPE_I)
+		info->pic_type = PIC_TYPE_I;
+	else
+		info->pic_type = PIC_TYPE_MAX;
+	if (inst->std == W_HEVC_DEC) {
+		if (info->pic_type == PIC_TYPE_I &&
+		    (info->nal_type == H265_NAL_UNIT_TYPE_IDR_W_RADL ||
+		     info->nal_type == H265_NAL_UNIT_TYPE_IDR_N_LP))
+			info->pic_type = PIC_TYPE_IDR;
+	} else if (inst->std == W_AVC_DEC) {
+		if (info->pic_type == PIC_TYPE_I &&
+		    info->nal_type == H264_NAL_UNIT_TYPE_IDR_PICTURE)
+			info->pic_type = PIC_TYPE_IDR;
+	}
+
+	reg_val = vpu_read_reg(inst->dev, W6_RET_DEC_DECODED_FLAG);
+	if (reg_val) {
+		struct frame_buffer fb;
+		dma_addr_t addr = vpu_read_reg(inst->dev, W6_RET_DEC_DECODED_ADDR);
+
+		fb = wave6_dec_get_display_buffer(inst, addr);
+		info->frame_decoded_addr = addr;
+		info->frame_decoded = true;
+		decoded_idx = fb.index;
+	}
+
+	reg_val = vpu_read_reg(inst->dev, W6_RET_DEC_DISPLAY_FLAG);
+	if (reg_val) {
+		struct frame_buffer fb;
+		dma_addr_t addr = vpu_read_reg(inst->dev, W6_RET_DEC_DISPLAY_ADDR);
+
+		fb = wave6_dec_get_display_buffer(inst, addr);
+		info->frame_display_addr = addr;
+		info->frame_display = true;
+		disp_idx = fb.index;
+	}
+
+	reg_val = vpu_read_reg(inst->dev, W6_RET_DEC_DISP_IDC);
+	for (i = 0; i < WAVE6_MAX_FBS; i++) {
+		if (reg_val & (1 << i)) {
+			dma_addr_t addr;
+
+			addr = vpu_read_reg(inst->dev, W6_RET_DEC_DISP_LINEAR_ADDR(i));
+
+			info->disp_frame_addr[info->disp_frame_num] = addr;
+			info->disp_frame_num++;
+		}
+	}
+
+	reg_val = vpu_read_reg(inst->dev, W6_RET_DEC_RELEASE_IDC);
+	for (i = 0; i < WAVE6_MAX_FBS; i++) {
+		if (reg_val & (1 << i)) {
+			dma_addr_t addr;
+
+			addr = vpu_read_reg(inst->dev, W6_RET_DEC_DISP_LINEAR_ADDR(i));
+
+			wave6_dec_remove_display_buffer(inst, addr);
+			info->release_disp_frame_addr[info->release_disp_frame_num] = addr;
+			info->release_disp_frame_num++;
+		}
+	}
+
+	if (inst->std == W_HEVC_DEC) {
+		info->decoded_poc = -1;
+		info->display_poc = -1;
+		if (decoded_idx >= 0)
+			info->decoded_poc = vpu_read_reg(inst->dev, W6_RET_DEC_PIC_POC);
+	} else if (inst->std == W_AVC_DEC) {
+		info->decoded_poc = -1;
+		info->display_poc = -1;
+		if (decoded_idx >= 0)
+			info->decoded_poc = vpu_read_reg(inst->dev, W6_RET_DEC_PIC_POC);
+	}
+
+	reg_val = vpu_read_reg(inst->dev, W6_RET_DEC_PIC_SIZE);
+	info->dec_pic_width = DEC_PIC_SIZE_WIDTH(reg_val);
+	info->dec_pic_height = DEC_PIC_SIZE_HEIGHT(reg_val);
+
+	info->rd_ptr = wave6_vpu_dec_get_rd_ptr(inst);
+	info->wr_ptr = p_dec_info->stream_wr_ptr;
+	info->byte_pos_frame_start = vpu_read_reg(inst->dev, W6_RET_DEC_AU_START_POS);
+	info->byte_pos_frame_end = vpu_read_reg(inst->dev, W6_RET_DEC_AU_END_POS);
+	info->stream_end = vpu_read_reg(inst->dev, W6_RET_DEC_STREAM_END);
+	info->notification_flags = vpu_read_reg(inst->dev, W6_RET_DEC_NOTIFICATION);
+	info->last_frame_in_au = vpu_read_reg(inst->dev, W6_RET_DEC_LAST_FRAME_FLAG);
+
+	reg_val = vpu_read_reg(inst->dev, W6_RET_DEC_TIMESTAMP_LOW);
+	info->timestamp = vpu_read_reg(inst->dev, W6_RET_DEC_TIMESTAMP_HIGH);
+	info->timestamp = (info->timestamp << 32) | reg_val;
+
+	info->cycle.host_cmd_s = vpu_read_reg(inst->dev, W6_RET_CQ_IN_TICK);
+	info->cycle.host_cmd_e = vpu_read_reg(inst->dev, W6_RET_RQ_OUT_TICK);
+	info->cycle.proc_s = vpu_read_reg(inst->dev, W6_RET_HW_RUN_TICK);
+	info->cycle.proc_e = vpu_read_reg(inst->dev, W6_RET_HW_DONE_TICK);
+	info->cycle.vpu_s = vpu_read_reg(inst->dev, W6_RET_FW_RUN_TICK);
+	info->cycle.vpu_e = vpu_read_reg(inst->dev, W6_RET_FW_DONE_TICK);
+	info->cycle.frame_cycle = (info->cycle.vpu_e - info->cycle.host_cmd_s) *
+				  CYCLE_PER_TICK_VALUE;
+	info->cycle.proc_cycle = (info->cycle.proc_e - info->cycle.proc_s) *
+				 CYCLE_PER_TICK_VALUE;
+	info->cycle.vpu_cycle = ((info->cycle.vpu_e - info->cycle.vpu_s) -
+				 (info->cycle.proc_e - info->cycle.proc_s)) *
+				 CYCLE_PER_TICK_VALUE;
+
+	if (decoded_idx >= 0 && decoded_idx < WAVE6_MAX_FBS)
+		p_dec_info->dec_out_info[decoded_idx].decoded_poc = info->decoded_poc;
+
+	if (disp_idx >= 0 && disp_idx < WAVE6_MAX_FBS) {
+		info->display_poc = p_dec_info->dec_out_info[disp_idx].decoded_poc;
+		info->disp_pic_width = p_dec_info->dec_out_info[disp_idx].dec_pic_width;
+		info->disp_pic_height = p_dec_info->dec_out_info[disp_idx].dec_pic_height;
+	}
+
+	info->sequence_no = p_dec_info->seq_info.sequence_no;
+	if (decoded_idx >= 0 && decoded_idx < WAVE6_MAX_FBS)
+		p_dec_info->dec_out_info[decoded_idx] = *info;
+
+	if (info->notification_flags & DEC_NOTI_FLAG_SEQ_CHANGE) {
+		wave6_get_dec_seq_result(inst, &p_dec_info->seq_info);
+		p_dec_info->seq_info.sequence_no++;
+	}
+
+	return 0;
+}
